package com.example.semestralka2;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class AppTest {
    @Test void appInitializes() {
        App classUnderTest = new App();
        assertNotNull(classUnderTest);
    }

    @Test
    void kdTreeSupportsNDimensions() {
        KDTree<Integer, String> tree = new KDTree<>(Integer::compare, 3);
        tree.insert(new Point<>(new Integer[]{1, 2, 3}, "A"));
        tree.insert(new Point<>(new Integer[]{8, 1, 0}, "B"));
        tree.insert(new Point<>(new Integer[]{2, 2, 2}, "C"));

        var found = tree.find(new Integer[]{0, 0, 0}, new Integer[]{3, 3, 3});
        assertEquals(2, found.size());
        assertTrue(found.stream().anyMatch(p -> p.getData().equals("A")));
        assertTrue(found.stream().anyMatch(p -> p.getData().equals("C")));
        assertTrue(found.stream().noneMatch(p -> p.getData().equals("B")));
    }

    @Test
    void quadTreeRespectsHeightLimit() {
        QuadTree<Integer, String> tree = new QuadTree<>(Integer::compare, 1);
        tree.insert(new Point<>(1, 1, "A"));
        tree.insert(new Point<>(9, 9, "B"));
        tree.insert(new Point<>(2, 8, "C"));

        var found = tree.find(0, 0, 10, 10);
        assertEquals(3, found.size());
    }
}
